const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function drawingLink(value){try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)?`<a class="drawing-link" href="${escape(url.href)}" target="_blank" rel="noopener noreferrer">Open ↗</a>`:'';}catch{return '';}}
export function partsRegister(parts){
 return `<div class="table-wrap"><table class="register-table"><thead><tr><th>Part</th><th>Material</th><th>Process</th><th class="quantity">Qty</th><th>Subsystem</th><th>CAD</th><th>Due</th></tr></thead><tbody>${parts.map(p=>`<tr><td><button class="part-name" data-edit="${escape(p.id)}">${escape(p.name)}</button><div class="part-number">${escape(p.number||'No number')}${p.blocked?' <span class="blocked-tag">Blocked</span>':''}</div></td><td>${escape(p.material)||'<span class="muted">Not set</span>'}</td><td>${escape(p.process)||'<span class="muted">Not set</span>'}</td><td class="quantity">${p.quantity}</td><td>${escape(p.subsystem)||'<span class="muted">Not set</span>'}</td><td>${drawingLink(p.cad)||'<span class="muted">-</span>'}</td><td>${p.due?escape(new Date(p.due+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'})):'<span class="muted">-</span>'}</td></tr>`).join('')}</tbody></table></div>`;
}
